T(61,1,"Зараз чи взагалі?","Розрізняти те, що відбувається зараз, і те, що буває завжди.",
 "Present Simple — звичка: I work in a bank (взагалі). Present Continuous — те, що відбувається зараз: I'm working now. Позначки часу: right now — просто зараз, currently і at present — на цей час, nowadays — нині, while — у той час як. Приклад: I'm cooking while he's reading.",
 [W("right now","/ˌraɪt ˈnaʊ/",P,"просто зараз","I'm busy right now.","Я зараз зайнятий."),
  W("currently","/ˈkʌrəntli/",AD,"на цей час","I'm currently studying English.","Зараз я вивчаю англійську."),
  W("nowadays","/ˈnaʊədeɪz/",AD,"нині","Nowadays I walk to work.","Нині я ходжу на роботу пішки."),
  W("at present","/ət ˈpreznt/",P,"наразі","She's at present on holiday.","Наразі вона у відпустці."),
  W("while","/waɪl/","conjunction","у той час як","I read while he cooks.","Я читаю, поки він готує.")],
 ("How do I get to the castle?","Повторимо. Прямо до розв'язки. Що відповісти?",["Go straight to the roundabout.","Go straight until roundabout to.","Straight go roundabout at."],"Go straight to the roundabout."),
 [("I'm busy right now.","Прослухайте. Що каже людина?",["Вона зараз зайнята","Вона завжди зайнята","Вона була зайнята"],"Right now."),
  ("I'm currently studying English.","Прослухайте. Що робить людина зараз?",["Вивчає англійську","Викладає англійську","Забула англійську"],"Studying."),
  ("I read while he cooks.","Прослухайте. Що робить людина?",["Читає, поки він готує","Готує, поки він читає","Читає, коли він спить"],"While.")],
 [("I'm busy ___.",["right now","every day","always"],"Right now — зараз."),
  ("___ I walk to work.",["Nowadays","Right now","While"],"Nowadays — нині."),
  ("I read ___ he cooks.",["while","right","now"],"While — у той час як.")],
 ("Що означає nowadays?",["нині","просто зараз","завжди"],"Nowadays — нині."),
 ("Я зараз зайнятий.",["I'm","busy","right","now"],["always","am"],"I'm busy right now."),
 ("Зараз я вивчаю англійську.",["I'm currently studying English","I am currently studying English"],"I'm currently studying English."),
 ("What are you doing right now?","Вивчаю англійську. Що відповісти?",["I'm studying English.","I study English right now.","I am study English."],"I'm studying English."))
